package io.fireflysoftware.experience.finance.terminal.web.posting;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import io.fireflysoftware.experience.finance.terminal.posting.*;
import io.fireflysoftware.experience.finance.terminal.posting.impl.StaffPostingServiceImpl;
import io.fireflysoftware.experience.finance.terminal.web.posting.impl.StaffPostingExceptionHandlerImpl;
import java.time.Instant;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import org.springframework.test.web.reactive.server.WebTestClient;
import reactor.core.publisher.Mono;
/** Controller-only HTTP contract; native JWT/exchange and default security are verified separately. */
class StaffPostingHttpContractTest {
    static final UUID ACTION=new UUID(0,3);
    static final String DIGEST="a".repeat(64),BASE="/api/v1/staff/tenants/"+new UUID(0,1)+"/books/"+new UUID(0,2)+"/ledger-journals";
    WebTestClient client(StaffPostingService service){return WebTestClient.bindToController(new StaffLedgerPostingsController(service)).controllerAdvice(new StaffPostingExceptionHandlerImpl()).build();}
    WebTestClient.RequestHeadersSpec<?> request(WebTestClient client,boolean recovery,String body){return client.post().uri(BASE+(recovery?"/recovery":"")).header(HttpHeaders.AUTHORIZATION,"Bearer aaa.bbb.ccc").contentType(MediaType.APPLICATION_JSON).bodyValue(body);}
    StaffPostingResponse result(StaffPostingResponse.Status status,Integer ownerStatus){return new StaffPostingResponse(ACTION,DIGEST,status,ownerStatus,ownerStatus,null);}
    @Test void absentBearerHasFixedPreDispatchEnvelopeAndCannotInvokeService(){var service=mock(StaffPostingService.class);client(service).post().uri(BASE).contentType(MediaType.APPLICATION_JSON).bodyValue("{}").exchange().expectStatus().isUnauthorized().expectHeader().valueEquals(HttpHeaders.CACHE_CONTROL,"no-store").expectBody().jsonPath("$.phase").isEqualTo("BEFORE_DOMAIN_DISPATCH").jsonPath("$.code").isEqualTo("STAFF_POSTING_PRE_DISPATCH_REJECTED").jsonPath("$.status").isEqualTo(401).jsonPath("$.actionId").doesNotExist();verifyNoInteractions(service);}
    @Test void malformedBearerCannotInvokeService(){var service=mock(StaffPostingService.class);client(service).post().uri(BASE).header(HttpHeaders.AUTHORIZATION,"Bearer malformed").contentType(MediaType.APPLICATION_JSON).bodyValue("{}").exchange().expectStatus().isUnauthorized().expectBody().jsonPath("$.phase").isEqualTo("BEFORE_DOMAIN_DISPATCH");verifyNoInteractions(service);}
    @Test void realStrictFacadeRejectsBeforeDomainWithDocumentedEnvelope(){var execution=mock(io.fireflysoftware.experience.finance.terminal.posting.StaffPostingExecution.class);request(client(new StaffPostingServiceImpl(execution)),false,"{}").exchange().expectStatus().isBadRequest().expectBody().jsonPath("$.phase").isEqualTo("BEFORE_DOMAIN_DISPATCH").jsonPath("$.status").isEqualTo(400).jsonPath("$.actionId").doesNotExist();verifyNoInteractions(execution);}
    @Test void unavailableAuthorityBeforeDispatchDoesNotClaimADomainOrCoreObservation(){var service=mock(StaffPostingService.class);when(service.submit(anyString(),anyString(),any(),eq(false))).thenReturn(Mono.error(new StaffPostingPreDispatchException(HttpStatus.SERVICE_UNAVAILABLE)));request(client(service),false,"{}").exchange().expectStatus().isEqualTo(503).expectBody().jsonPath("$.phase").isEqualTo("BEFORE_DOMAIN_DISPATCH").jsonPath("$.status").isEqualTo(503).jsonPath("$.ownerStatus").doesNotExist();}
    @Test void everySupportedOwnerRefusalRetainsExactStatusAndOriginalCorrelation(){for(int status:new int[]{400,401,403,404,409,410,418,422,451}){var service=mock(StaffPostingService.class);when(service.submit(anyString(),anyString(),any(),eq(false))).thenReturn(Mono.just(result(StaffPostingResponse.Status.CURRENT_INVOCATION_REFUSED,status)));request(client(service),false,"{}").exchange().expectStatus().isEqualTo(status).expectHeader().valueEquals(HttpHeaders.CACHE_CONTROL,"no-store").expectBody().jsonPath("$.actionId").isEqualTo(ACTION.toString()).jsonPath("$.intentDigest").isEqualTo(DIGEST).jsonPath("$.status").isEqualTo("CURRENT_INVOCATION_REFUSED").jsonPath("$.ownerStatus").isEqualTo(status).jsonPath("$.phase").doesNotExist();verify(service,times(1)).submit(anyString(),anyString(),any(),eq(false));}}
    @Test void uncertainAndKnownCommitUnavailableRetainOriginalActionWithoutReceipt(){for(var status:new StaffPostingResponse.Status[]{StaffPostingResponse.Status.OUTCOME_UNKNOWN,StaffPostingResponse.Status.COMMITTED_RESPONSE_UNAVAILABLE}){var service=mock(StaffPostingService.class);when(service.submit(anyString(),anyString(),any(),eq(false))).thenReturn(Mono.just(result(status,null)));request(client(service),false,"{}").exchange().expectStatus().isEqualTo(503).expectBody().jsonPath("$.actionId").isEqualTo(ACTION.toString()).jsonPath("$.intentDigest").isEqualTo(DIGEST).jsonPath("$.status").isEqualTo(status.name()).jsonPath("$.phase").doesNotExist();}}
    @Test void missingRecoveryObservationPreservesActionAndRecoveryRoute(){var service=mock(StaffPostingService.class);when(service.submit(anyString(),anyString(),any(),eq(true))).thenReturn(Mono.just(result(StaffPostingResponse.Status.NOT_OBSERVED,404)));request(client(service),true,"{}").exchange().expectStatus().isNotFound().expectBody().jsonPath("$.actionId").isEqualTo(ACTION.toString()).jsonPath("$.status").isEqualTo("NOT_OBSERVED").jsonPath("$.ownerStatus").isEqualTo(404);verify(service,times(1)).submit(anyString(),anyString(),any(),eq(true));}
    @Test void committedReceiptIsTypedWithInstantAndNoStore(){var service=mock(StaffPostingService.class);var receipt=new StaffPostingReceipt(new UUID(0,4),ACTION,new UUID(0,5),1,DIGEST,false,Instant.parse("2026-11-01T12:00:00Z"));when(service.submit(anyString(),anyString(),any(),eq(false))).thenReturn(Mono.just(new StaffPostingResponse(ACTION,DIGEST,StaffPostingResponse.Status.COMMITTED,200,200,receipt)));request(client(service),false,"{}").exchange().expectStatus().isOk().expectHeader().valueEquals(HttpHeaders.CACHE_CONTROL,"no-store").expectBody().jsonPath("$.status").isEqualTo("COMMITTED").jsonPath("$.receipt.actionId").isEqualTo(ACTION.toString()).jsonPath("$.receipt.recordedAt").isEqualTo("2026-11-01T12:00:00Z");}
}
